import{_ as a,o as r,c as d,ai as l}from"./chunks/framework.ampVZV4B.js";const c=JSON.parse('{"title":"机会评估框架","description":"","frontmatter":{},"headers":[],"relativePath":"ai/business/opportunity-scan.md","filePath":"ai/business/opportunity-scan.md"}'),i={name:"ai/business/opportunity-scan.md"};function e(n,t,o,s,h,p){return r(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="机会评估框架" tabindex="-1">机会评估框架 <a class="header-anchor" href="#机会评估框架" aria-label="Permalink to “机会评估框架”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>从上一篇的挖掘流程里，你可能一次捞出了三五个「好像可以做」的想法。此时最危险的动作是凭感觉挑一个顺眼的开干——感觉通常偏向你最熟的、最新奇的，而不是最值得做的。凭热情启动的项目，往往死在第 3 个月的热情消退期。</p><p>这篇给出一套我实际在用的打分框架：把模糊的「感觉有机会」拆成四个可打分的维度，先用分数粗筛，再用「先小后大」的节奏投入。目的不是算出精确结论——纸上评估永远算不准——而是<strong>让不同的想法可以在同一把尺子下比较</strong>，并逼你想清楚那些没答案的问题。</p><h2 id="拆解" tabindex="-1">拆解 <a class="header-anchor" href="#拆解" aria-label="Permalink to “拆解”">​</a></h2><h3 id="_1-四个评估维度" tabindex="-1">1. 四个评估维度 <a class="header-anchor" href="#_1-四个评估维度" aria-label="Permalink to “1. 四个评估维度”">​</a></h3><p><strong>维度一：市场规模（这个池子有多大）</strong></p><p>不需要精确测算，量级判断就够：</p><ul><li>目标人群能不能一句话说清（「所有互联网从业者」= 说不清，不算数）；</li><li>人群规模粗估：十万级、百万级、千万级；</li><li>付费天花板：人均每年能贡献多少（几十、几百、几千）。</li></ul><p>副业项目的真实体感是：<strong>哪怕十万人群 × 10% 触达 × 100 元客单，也远超你能交付的上限</strong>。所以这一维不必追求大，够且真实即可——池子描述不清才是硬伤。</p><p><strong>维度二：竞争（谁已经在这里）</strong></p><ul><li>搜一圈，有没有成熟产品？收费吗？</li><li>竞品的差评区在抱怨什么？那是你的切入点；</li><li>完全没有竞品 ≠ 好事，大概率意味着没需求（前面三把尺子再过一遍）；</li><li>有竞品但都很烂、很老、不更新 → 这是最理想的「有验证、有空位」。</li></ul><p><strong>维度三：优势匹配（凭什么是你）</strong></p><p>诚实回答：这个方向用到你的哪些存量资产——Java/全栈功底、某行业业务认知、已有的粉丝/客户、某个平台的熟练度？一条都对不上，你就是在用最短的板去和别人的长板碰。<strong>优势匹配度是四个维度里权重最高的</strong>，因为它决定你的获客成本和交付质量。</p><p><strong>维度四：切入成本（多快能开始收钱/验证）</strong></p><ul><li>冷启动要几个月？（写代码 2 个月 vs 两周出落地页）</li><li>需要资质、服务器、客服、库存吗？</li><li>最小验证动作是什么、花多少钱？</li></ul><p>业余时间做项目，<strong>切入成本是存活率的分母</strong>：周期越长，被生活打断、热情耗尽的概率越大。</p><h3 id="_2-打分表" tabindex="-1">2. 打分表 <a class="header-anchor" href="#_2-打分表" aria-label="Permalink to “2. 打分表”">​</a></h3><p>每个维度 1-5 分，先独立打分再相乘或加权。我的参考标准：</p><table tabindex="0"><thead><tr><th>维度</th><th>1 分</th><th>3 分</th><th>5 分</th></tr></thead><tbody><tr><td>市场规模</td><td>人群说不清或极小</td><td>人群可描述，十万级</td><td>百万级人群、付费有先例</td></tr><tr><td>竞争</td><td>无竞品（可能无需求）</td><td>有竞品，红海但有差评空位</td><td>有付费验证的竞品，其差评明确</td></tr><tr><td>优势匹配</td><td>完全陌生领域</td><td>有点相关经验</td><td>存量技能/客户直接复用</td></tr><tr><td>切入成本</td><td>冷启动 &gt;3 个月</td><td>1-2 个月</td><td>两周内可验证</td></tr></tbody></table><p>示意性打分（仅为演示用法，非真实项目）：</p><table tabindex="0"><thead><tr><th>候选想法</th><th>市场</th><th>竞争</th><th>优势</th><th>成本</th><th>合计</th><th>判断</th></tr></thead><tbody><tr><td>例如：面向运维人群的配置比对小工具</td><td>3</td><td>4</td><td>5</td><td>4</td><td>16</td><td>优先做</td></tr><tr><td>例如：通用 AI 写作平台</td><td>5</td><td>1</td><td>2</td><td>2</td><td>10</td><td>放弃</td></tr></tbody></table><p>两个使用纪律：<strong>总分不及单项</strong>——优势匹配 1 分的想法，市场 5 分也建议直接淘汰；<strong>打不出分的格子是调研任务</strong>——「竞品那格我不知道填几」说明该去用一天搜竞品，而不是瞎填。</p><h3 id="_3-先小后大-用阶段门控控制投入" tabindex="-1">3. 先小后大：用阶段门控控制投入 <a class="header-anchor" href="#_3-先小后大-用阶段门控控制投入" aria-label="Permalink to “3. 先小后大：用阶段门控控制投入”">​</a></h3><p>打分通过不等于 all in，而是拿到「花小钱试一次」的资格。建议三阶段：</p><ol><li><strong>试探期（1-2 周）</strong>：只做验证动作——发个 landing page、在目标社群发条介绍、找 5 个潜在用户聊。花的是时间，不是钱；</li><li><strong>小步期（1-2 月）</strong>：有信号才做 MVP，功能砍到只剩核心闭环，先收费再迭代；</li><li><strong>加注期</strong>：数据证明有人持续用、持续付费，才考虑投入更多时间甚至考虑全职化。</li></ol><p>每阶段设明确的<strong>继续/止损条件</strong>（具体指标见「低成本 MVP 验证」一文），到点不达标就停。框架的价值就在这：让「放弃」成为一个按流程执行的正常动作，而不是对自我的否定。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>打分的目的是横向比较和暴露盲区，不是算出精确期望值——算不准没关系，说不出口的问题才是收获；</li><li>四维度：市场（池子说清没）、竞争（差评区即切入点）、优势匹配（权重最高，决定成本）、切入成本（决定存活率）；</li><li>单项 1 分一票否决，打不出分的格子是调研任务，不是填空题；</li><li>过筛只获得「小额试探资格」，不是 all in 许可；三阶段门控：试探期 → 小步期 → 加注期；</li><li>到预设止损条件就停，把放弃做成流程动作而非情绪决定。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>机会评估框架本质上是在和自己的乐观偏差对抗：人天然会高估喜欢的想法，低估讨厌的麻烦。四个维度各打 1-5 分，花不了半天，却能在你投入三个月之前，把「这个好像不行」提前到「这个分数不行」。对第一次做副业的人，它的最大价值是——<strong>让你系统性地少做一个项目</strong>，把省下的时间压到真正过筛的那一个上。</p>',31)])])}const b=a(i,[["render",e]]);export{c as __pageData,b as default};
